// Detects whether an ignore list still contains a given entry.
//
// Used by check-agent-docs.mjs to prove that .prettierignore, eslint.config.mjs, and
// vitest.config.ts ignore the same tooling-state directories, which is what makes the verification
// exemption in AGENTS.md sound.
//
// Matching is deliberately not line-based. Prettier collapses a short array onto one line, so a
// per-line check would report a correctly formatted config as broken, and a commented-out entry
// must never read as present.

/** Blanks out `//` line comments and `/* *\/` block comments so neither can satisfy a match. */
export function stripComments(source) {
  const withoutBlocks = source.replace(/\/\*[\s\S]*?\*\//g, "");

  return withoutBlocks
    .split("\n")
    .map((line) => (line.trimStart().startsWith("//") ? "" : line))
    .join("\n");
}

/** Gitignore syntax: one entry per line, `#` comments, exact match only. */
export function hasGitignoreEntry(contents, entry) {
  return contents.split("\n").some((line) => {
    const trimmed = line.trim();

    if (trimmed === "" || trimmed.startsWith("#")) return false;

    return trimmed === entry;
  });
}

/** JavaScript or TypeScript source: a quoted string token, in any array layout. */
export function hasQuotedEntry(source, entry) {
  const escaped = entry.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

  return new RegExp(`(["'\`])${escaped}\\1`).test(stripComments(source));
}

