import { describe, expect, it } from "vitest";

import { hasGitignoreEntry, hasQuotedEntry, stripComments } from "./ignore-entries.mjs";

describe("hasGitignoreEntry", () => {
  it("matches an entry on its own line", () => {
    expect(hasGitignoreEntry(".next\n.claude\n.vercel\n", ".claude")).toBe(true);
  });

  it("tolerates surrounding whitespace", () => {
    expect(hasGitignoreEntry("  .claude  \n", ".claude")).toBe(true);
  });

  it("reports a missing entry", () => {
    expect(hasGitignoreEntry(".next\n.vercel\n", ".claude")).toBe(false);
  });

  it.each(["# .claude", "#.claude", "!.claude", ".claude-old", "docs/.claude", ".claude/agents"])(
    "does not accept %j as the entry",
    (line) => {
      expect(hasGitignoreEntry(`${line}\n`, ".claude")).toBe(false);
    },
  );
});

describe("hasQuotedEntry", () => {
  it("matches an expanded array", () => {
    const source = ['exclude: [', '  "**/node_modules/**",', '  ".claude/**",', "]"].join("\n");

    expect(hasQuotedEntry(source, ".claude/**")).toBe(true);
  });

  it("matches an array Prettier collapsed onto one line", () => {
    expect(hasQuotedEntry('exclude: ["**/node_modules/**", ".claude/**"],', ".claude/**")).toBe(
      true,
    );
  });

  it("matches regardless of quote style", () => {
    expect(hasQuotedEntry("['.claude/**']", ".claude/**")).toBe(true);
  });

  it("reports a missing entry", () => {
    expect(hasQuotedEntry('exclude: ["**/node_modules/**"]', ".claude/**")).toBe(false);
  });

  it("does not accept a line-commented entry", () => {
    expect(hasQuotedEntry('  // ".claude/**",', ".claude/**")).toBe(false);
  });

  it("does not accept a block-commented entry", () => {
    expect(hasQuotedEntry('/*\n  ".claude/**",\n*/', ".claude/**")).toBe(false);
  });

  it("does not accept a block comment on one line", () => {
    expect(hasQuotedEntry('/* ".claude/**", */', ".claude/**")).toBe(false);
  });

  it.each(['".claude-old/**"', '"docs/.claude/**"', '"**/.claude/**"', '".claude/**/*"'])(
    "does not accept %s as the entry",
    (token) => {
      expect(hasQuotedEntry(`exclude: [${token}]`, ".claude/**")).toBe(false);
    },
  );

  it("treats the entry as a literal rather than a pattern", () => {
    expect(hasQuotedEntry('["Xclaude/XX"]', ".claude/**")).toBe(false);
  });
});

describe("stripComments", () => {
  it("preserves code outside comments", () => {
    expect(stripComments('const a = 1; // note\n"keep"')).toContain('"keep"');
  });

  it("does not treat a URL inside a string as a comment", () => {
    expect(stripComments('const url = "https://example.com/.claude/**";')).toContain("example.com");
  });
});

// Detects whether an ignore list still contains a given entry.
//
// Used by check-agent-docs.mjs to prove that .prettierignore, eslint.config.mjs, and
// vitest.config.ts ignore the same tooling-state directories, which is what makes the verification
// exemption in AGENTS.md sound.
//
// Matching is neither line-based nor regex-based over the raw source. Prettier collapses a short
// array onto one line, so a per-line check would report a correctly formatted config as broken.
// Stripping comments with a regex is worse: the `/*` inside a glob such as "**/node_modules/**"
// reads as a block-comment opener, so a pure reorder of the array would corrupt the scan. Instead,
// walk the source once and yield only real string literals, which cannot be confused with either.

/**
 * Yields the value of every string literal in `source`, skipping comments. A `/*` or `//` inside a
 * string is literal text, because a string is consumed as a unit before comment detection resumes.
 */
export function* stringLiterals(source) {
  let index = 0;

  while (index < source.length) {
    const character = source[index];
    const following = source[index + 1];

    if (character === "/" && following === "/") {
      while (index < source.length && source[index] !== "\n") index += 1;
      continue;
    }

    if (character === "/" && following === "*") {
      index += 2;
      while (index < source.length && !(source[index] === "*" && source[index + 1] === "/")) {
        index += 1;
      }
      index += 2;
      continue;
    }

    if (character === '"' || character === "'" || character === "`") {
      const quote = character;
      let value = "";
      index += 1;

      while (index < source.length && source[index] !== quote) {
        if (source[index] === "\\") {
          value += source[index + 1] ?? "";
          index += 2;
          continue;
        }

        value += source[index];
        index += 1;
      }

      index += 1;
      yield value;
      continue;
    }

    index += 1;
  }
}

/** Gitignore syntax: one entry per line, `#` comments, exact match only. */
export function hasGitignoreEntry(contents, entry) {
  return contents.split("\n").some((line) => {
    const trimmed = line.trim();

    if (trimmed === "" || trimmed.startsWith("#")) return false;

    return trimmed === entry;
  });
}

/** JavaScript or TypeScript source: a string literal equal to `entry`, in any array layout. */
export function hasQuotedEntry(source, entry) {
  for (const value of stringLiterals(source)) {
    if (value === entry) return true;
  }

  return false;
}

