function gateBlock(markdown, firstCommand) {
  // Every fence must be consumed, including `text` and `env` ones. Matching only bash fences skips
  // an unmatched block's opening fence and then reads its closing fence as an opener, which turns
  // the prose after it into a phantom block.
  for (const [, info, body] of markdown.matchAll(/```([^\n]*)\n([\s\S]*?)```/g)) {
